'use client';

import * as React from 'react';
import { RadioGroup } from '@base-ui/react/radio-group';
import { Radio } from '@base-ui/react/radio';
import { SlidingIndicator } from '../../motion/indicator';
import './segmented.css';

/* ─────────────────────────────────────────────────────────
 * SEGMENTED CONTROL (KAMUI-04) on Base UI RadioGroup
 *
 *   rest      a well track; segments in ink2, the selected one a raised thumb in ink
 *   hover     the label turns ink (settle)
 *   select    the thumb glides to the new segment on the part spring (a track with
 *             ends, so it may overshoot against the stop); labels recolour on settle
 *   focus     a 1.5 ring with no offset (a dense strip); arrows move the selection
 *   disabled  40 %
 * First paint and resizing place the thumb without motion. Reduce Motion: it moves at once.
 * ───────────────────────────────────────────────────────── */

export interface SegmentedOption<V extends string = string> {
  value: V;
  label: React.ReactNode;
  /** A leading glyph at the size the height gives (12 in 24, 14 in 28). */
  icon?: React.ReactNode;
  disabled?: boolean;
}

export interface SegmentedProps<V extends string = string> {
  options: SegmentedOption<V>[];
  value?: V;
  defaultValue?: V;
  onValueChange?: (value: V) => void;
  /** compact is 24 tall (in a lens bar, a strip), regular 28. */
  size?: 'compact' | 'regular';
  disabled?: boolean;
  'aria-label': string;
  className?: string;
}

/** A pill of pills: one of a few views or modes, always visible. */
export function Segmented<V extends string = string>({ options, value, defaultValue, onValueChange, size = 'regular', disabled, className, ...props }: SegmentedProps<V>) {
  return (
    <RadioGroup
      value={value}
      defaultValue={defaultValue}
      onValueChange={(v) => onValueChange?.(v as V)}
      disabled={disabled}
      aria-label={props['aria-label']}
      data-size={size}
      className={className ? `mu-segmented ${className}` : 'mu-segmented'}
    >
      <SlidingIndicator className="mu-segmented-thumb" />
      {options.map((o) => (
        <Radio.Root key={o.value} value={o.value} disabled={o.disabled} className="mu-segment type-ui">
          {o.icon}
          {o.label}
        </Radio.Root>
      ))}
    </RadioGroup>
  );
}

@import "../tokens.css";

/* Segmented control (KAMUI-04): a pill of pills on Base UI RadioGroup. */
.mu-segmented {
  position: relative;
  display: inline-flex;
  padding: var(--mu-segmented-track-pad);
  border-radius: 999px;
  background: linear-gradient(var(--mu-well-top), var(--mu-well-bot));
  box-shadow: var(--mu-well);
}
.mu-segment {
  --h: var(--mu-segmented-regular);
  position: relative;
  z-index: 1;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: var(--h);
  /* The pill rule: text first, h/2 − 1. */
  padding: 0 calc(var(--h) / 2 - 1px);
  margin: 0;
  border: 0;
  border-radius: 999px;
  background: transparent;
  white-space: nowrap;
  color: var(--mu-ink2);
  cursor: pointer;
  transition: color var(--mu-spring-settle-d) var(--mu-spring-settle);
  -webkit-tap-highlight-color: transparent;
}
.mu-segmented[data-size="compact"] .mu-segment { --h: var(--mu-segmented-compact); }
.mu-segment:hover { color: var(--mu-ink); }
.mu-segment[data-checked] { color: var(--mu-ink); }
.mu-segment:focus-visible { outline: var(--mu-segmented-focus-width) solid var(--mu-focus); outline-offset: 0; }
.mu-segment[data-disabled] { opacity: .4; cursor: default; }
.mu-segmented[data-disabled] { opacity: .4; }
/* The thumb: a raised cap that glides on the part spring (SlidingIndicator). */
.mu-segmented > .mu-segmented-thumb {
  border-radius: 999px;
  background: linear-gradient(var(--mu-thumb-hi), var(--mu-thumb-lo));
  box-shadow: var(--mu-raise-sm);
}
